                //Add a paragraph to a section
                IWParagraph paragraph = section.AddParagraph();
                //Append the text to paragraph
                paragraph.AppendText("Working with footnotes");
                //Formatting the text
                paragraph.ApplyStyle(BuiltinStyle.Heading1);
