The following example illustrates how to access and modify editable ranges in a Word document. 

// Load an existing Word document into the DocIO instance 
IWordDocument document = new WordDocument("Template.docx"); 
// Get the collection of editable ranges from the document 
EditableRangeCollection editableRangeCollection = document.EditableRanges; 
// Modify the SingleUser property of the first editable range 
editableRangeCollection[0].SingleUser = "user@domain.com"; 
// Save the document to the specified file and format 
document.Save("Sample.docx", FormatType.Docx); 
// Close the document and release resources 
document.Close(); 


